CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PUESTOHERMAN" ("IDPUESTO", "INTERPRETACION", "INTERPRETACION1", "INTERPRETACION2", "INTERPRETACION3", "INTERPRETACION4", "INTERPRETACION5", "NOMBRE", "NOMBRE1", "NOMBRE2", "NOMBRE3", "NOMBRE4", "NOMBRE5") AS 
  SELECT PuestoInterpretacion.IdPuesto, Interpretacion.Interpretacion, Interpretacion_1.Interpretacion as Interpretacion1, Interpretacion_2.Interpretacion as Interpretacion2, Interpretacion_3.Interpretacion as Interpretacion3, Interpretacion_4.Interpretacion as Interpretacion4, Interpretacion_5.Interpretacion as Interpretacion5, Interpretacion.Nombre, Interpretacion_1.Nombre as nombre1, Interpretacion_2.Nombre as nombre2, Interpretacion_3.Nombre as nombre3, Interpretacion_4.Nombre as nombre4, Interpretacion_5.Nombre as nombre5
 FROM (((((PuestoInterpretacion LEFT JOIN Interpretacion ON PuestoInterpretacion.IdInterpretacion1 = Interpretacion.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_1 ON PuestoInterpretacion.IdInterpretacion2 = Interpretacion_1.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_2 ON PuestoInterpretacion.IdInterpretacion3 = Interpretacion_2.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_3 ON PuestoInterpretacion.IdInterpretacion4 = Interpretacion_3.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_4 ON PuestoInterpretacion.IdInterpretacion5 = Interpretacion_4.IdInterpretacion) LEFT JOIN Interpretacion Interpretacion_5 ON PuestoInterpretacion.IdInterpretacion6 = Interpretacion_5.IdInterpretacion
 WHERE (((PuestoInterpretacion.IdPrueba)=5));
